 MZ("EL SIGNO DE LA VARIACIÓN",[("Positiva","Hubo un aumento"),("Negativa","Hubo una disminución"),("Cero","No hubo cambio"),("−100 %","Llegó a cero")],["El signo de la variación cuenta una historia.","Si es *positiva*, hubo un aumento.","Si es *negativa*, hubo una disminución.","Si es *cero*, no cambió nada.","Y una variación de menos cien por ciento significa que la cantidad *llegó a cero*."]),
 QZ("Un precio baja de $80 a $60. ¿Cuál fue la variación?",["−25 %","−20 %","+25 %"],0,["Te toca: el precio baja de ochenta a sesenta pesos.","Se resta, se divide por el valor inicial y se pasa a porcentaje.","Da menos cero coma veinticinco: *menos veinticinco por ciento*."]),
